/bin/bash -lc "python3 - <<'PY'
import ast,json,subprocess,hashlib
from pathlib import Path
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True));p=json.loads(Path('proposal.json').read_text())
def check(v,s,path):
 typ=s.get('type');types={'object':dict,'array':list,'string':str,'boolean':bool}
 if typ: assert isinstance(v,types[typ]),(path,'type')
 if 'const' in s:assert v==s['const'],(path,'const')
 if 'enum' in s:assert v in s['enum'],(path,'enum')
 if isinstance(v,dict):
  assert set(s.get('required',[]))<=set(v),(path,'missing')
  if s.get('additionalProperties') is False:assert set(v)<=set(s.get('properties',{})),(path,'unknown')
  for k,x in v.items():
   if k in s.get('properties',{}):check(x,s['properties'][k],path+'.'+k)
 if isinstance(v,list):
  assert len(v)>=s.get('minItems',0),(path,'minItems')
  if 'items' in s:
   for i,x in enumerate(v):check(x,s['items'],path+'.'+str(i))
 if isinstance(v,str):assert len(v)>=s.get('minLength',0),(path,'minLength')
check(p['study'],r['study_schema'],'study')
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
for v in p['variants']:
 assert v['file']==Path(v['file']).name and v['file'].endswith('.py')
 t=ast.parse(Path(v['file']).read_text())
 cfg=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert cfg==v['config']
 assert v['role'] in ('control','candidate')
 # Count keys emitted by final diagnostics, including fixed loop unrolling.
 diag=next(n for n in t.body[-1].body if isinstance(n,ast.FunctionDef) and n.name=='diagnostics')
 d=next(n for n in ast.walk(diag) if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='result' for x in n.targets))
 count=len(d.value.keys)+2*2+2*2*2+2*2
 assert count==41 and count<=64
 assert hashlib.sha256(Path(v['file']).read_bytes()).hexdigest() in v['note']
assert hashlib.sha256(Path('candidate.py').read_bytes()).hexdigest()=='01e410b5ceedadc13edb3a2e5132500b7e19a24a5f0a89ddf4ab2c4cc2cda958'
assert Path('candidate.py').read_bytes()==Path('history_r0033_gap_factorized_symmetric.py').read_bytes()
print(json.dumps({'schema':'passed exact runtime study schema','registered_configs':'all3 match literal CONFIG','diagnostics':41,'incumbent':'unchanged exact archived bytes','authorized_evidence_ids':'passed','budget_hard_caps_plus_reserves':3*r['context']['protocol']['trial_cap_seconds']+21000,'remaining_snapshot':r['context']['remaining_seconds'],'new_host_evaluations':0},indent=2))
PY"

